package net.civeira.phylax.feature.identity.tenant.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenant.domain.Tenant;
import net.civeira.phylax.feature.identity.tenant.domain.valueobject.RootVO;

class RootValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of root of tenant")
  void test_root_value_holder_assign_plain_value() {
    Object holder = new Object();
    RootValueHolder<Object> value = new RootValueHolder<>(holder);
    Assertions.assertSame(holder, value.root(true), "Setters must return the holder");
    Assertions.assertTrue(value.getRootValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(true, value.getRoot().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.rootNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getRootValue().isPresent(), "A null value object must be stored");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of root of tenant")
  void test_root_value_holder_assign_value_object() {
    Object holder = new Object();
    RootValueHolder<Object> value = new RootValueHolder<>(holder);
    RootVO vo = RootVO.from(true);
    Assertions.assertFalse(value.getRootValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.root(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getRootValue().orElseThrow());
    Assertions.assertSame(holder, value.root(Optional.empty()));
    Assertions.assertFalse(value.getRootValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.root(Optional.of(vo)));
    Assertions.assertSame(vo, value.getRootValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of root of tenant against the original")
  void test_root_value_holder_read() {
    Object holder = new Object();
    RootValueHolder<Object> value = new RootValueHolder<>(holder);
    RootVO vo = RootVO.from(true);
    RootVO other = RootVO.from(true);
    Tenant original = Mockito.mock(Tenant.class);
    Mockito.when(original.getRootValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readRoot(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readRoot(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.root(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readRoot(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readRoot(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of root of tenant")
  void test_root_value_holder_unset() {
    Object holder = new Object();
    RootValueHolder<Object> value = new RootValueHolder<>(holder);
    RootVO vo = RootVO.from(true);
    value.root(vo);
    Assertions.assertSame(holder, value.unsetRootIfMatches("root_other"));
    Assertions.assertTrue(value.getRootValue().isPresent(), "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetRootIfMatches("root"));
    Assertions.assertFalse(value.getRootValue().isPresent(), "The field name must clear the value");
    value.root(vo);
    Assertions.assertSame(holder, value.unsetRoot());
    Assertions.assertFalse(value.getRootValue().isPresent(), "Unset must clear the value");
  }
}
